-- One-time import: HubSpot marketing contacts (opted in) onto the Corrections, Employers and Treatment centers lists.
-- Checked against existing contacts by email: nobody is added twice, and contacts already sorted onto a list or
-- set aside keep that decision. A summary per list is printed to the deploy log.
create temp table hs_lists (list text, email text, first_name text, last_name text, company text, address text, address2 text, city text, state text, zip text, phone text) on commit drop;

do $$
declare l text; total int; existing int; moved int; added int; leads int;
begin
  foreach l in array array['corrections', 'employers', 'treatment'] loop
    select count(distinct lower(email)) into total from hs_lists where list = l;
    select count(*) into existing from contact_imports c where lower(c.email) in (select lower(email) from hs_lists where list = l);
    select count(distinct lower(x.email)) into leads from leads x where lower(x.email) in (select lower(email) from hs_lists where list = l);

    select distinct on (lower(h.email)) lower(h.email), h.first_name, h.last_name, h.company, h.address, h.address2, h.city, h.state, h.zip, h.phone,
      'hubspot', 'HubSpot ' || l || ' contacts (2026-11-22)', l, 'assigned', now()
    from hs_lists h
    where h.list = l and not exists (select 1 from contact_imports c where lower(c.email) = lower(h.email))
    order by lower(h.email);
    get diagnostics added = row_count;

    update contact_imports c set status = 'assigned', list = l, assigned_at = now(), updated_at = now()
    where c.status = 'pending' and lower(c.email) in (select lower(email) from hs_lists where list = l);
    get diagnostics moved = row_count;

    raise notice '[% import] % in file; % new contacts added; % already on file (% moved from Pending, % left on their existing list or set aside); % also match website leads',
      l, total, added, existing, moved, existing - moved, leads;
  end loop;
end $$;
